# 用法：于本目录跑 python build_p.py → 写 ../*_new.csv、../fixes_*.csv（不动 data/csv/）
import csv, os
HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.abspath(os.path.join(HERE, ".."))
CSV = os.path.abspath(os.path.join(HERE, "..", "..", "..", "..", "csv"))

def hdr(t):
    with open(os.path.join(CSV, t + ".csv"), encoding="utf-8", newline="") as f:
        return next(csv.reader(f))
def main_rows(t):
    with open(os.path.join(CSV, t + ".csv"), encoding="utf-8", newline="") as f:
        return list(csv.DictReader(f))
def write(fn, t, rows):
    h = hdr(t)
    with open(os.path.join(OUT, fn), "w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=h, lineterminator="\n")
        w.writeheader()
        for r in rows:
            assert set(r) == set(h), (fn, set(h) ^ set(r))
            w.writerow(r)

WK = "维基文库整理本《春秋左氏傳》（`action=raw`，2026-10-17 实取，`_method/diben/`）"
NOTE_DIBEN = "【底本】" + WK + "；标点系本库整理所加，用字逐字照底本（sim 去标点比字）；只一本，未双本互校，纸本未核。"

